INSERT INTO "handover_interviews" ("id", "handover_id", "topic", "topic_ref_type", "topic_ref_id", "transcript_json", "structured_json", "status", "insight_lesson_id", "created_at", "updated_at") VALUES
('01M4D6DC0XG3DCJKMMS7MJCYCE', '01M4D6DBY724ESZY5SW645WDA5', 'PRJ-15a Industrial Symbiosis Pilot', 'node', '01M4D6BHKA2PN56NN1E3X2X84X', '[{"role":"ai","text":"What is the current status of PRJ-15a Industrial Symbiosis Pilot, and what is the next milestone a successor must not miss?","en":"What is the current status of PRJ-15a Industrial Symbiosis Pilot, and what is the next milestone a successor must not miss?","ar":"ما الوضع الحالي لـ PRJ-15a Industrial Symbiosis Pilot، وما المحطة التالية التي لا ينبغي للخلف أن يفوّتها؟","at":"2026-10-08T07:24:59.805Z"},{"role":"person","text":"The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules.","at":"2026-10-08T07:24:59.806Z"},{"role":"ai","text":"Which decisions shaped this work so far, and why were they taken?","en":"Which decisions shaped this work so far, and why were they taken?","ar":"ما القرارات التي شكّلت هذا العمل حتى الآن، ولماذا اتُّخذت؟","at":"2026-10-08T07:24:59.806Z"},{"role":"person","text":"We decided in March to move field data capture to tablets after the 2025 pilot cut the number of repeat site visits; the Programme Director approved it and the budget came from the data programme.","at":"2026-10-08T07:24:59.807Z"},{"role":"ai","text":"Who are the people a successor must know, inside Programme Office and outside it, and what does each one care about?","en":"Who are the people a successor must know, inside Programme Office and outside it, and what does each one care about?","ar":"من الأشخاص الذين ينبغي للخلف معرفتهم داخل المكتب وخارجه، وما الذي يهم كل واحد منهم؟","at":"2026-10-08T07:24:59.807Z"},{"role":"person","text":"Inside the Office, Saud Al-Shammari owns the operations calendar and Mohammed Al-Qarni runs the field teams. Outside, the contact at MEWA is the monitoring unit head, who cares about station location quality.","at":"2026-10-08T07:24:59.807Z"},{"role":"ai","text":"What went wrong or nearly went wrong, and what should a successor avoid?","en":"What went wrong or nearly went wrong, and what should a successor avoid?","ar":"ما الذي أخفق أو كاد أن يخفق، وما الذي ينبغي للخلف تجنبه؟","at":"2026-10-08T07:24:59.807Z"},{"role":"person","text":"The 2024 round slipped because the station register arrived late. Lock the register delivery date in writing and never start training before the data capture form is frozen.","at":"2026-10-08T07:24:59.808Z"},{"role":"ai","text":"Where do the files, the data and the working papers live, and who holds access to them?","en":"Where do the files, the data and the working papers live, and who holds access to them?","ar":"أين تُحفظ الملفات والبيانات وأوراق العمل، ومن يملك صلاحية الوصول إليها؟","at":"2026-10-08T07:24:59.808Z"},{"role":"person","text":"The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account.","at":"2026-10-08T07:24:59.808Z"},{"role":"ai","text":"If you had one hour with your successor, what would you tell them first?","en":"If you had one hour with your successor, what would you tell them first?","ar":"لو كان لديك ساعة واحدة مع خلفك، فما أول ما ستخبره به؟","at":"2026-10-08T07:24:59.808Z"},{"role":"person","text":"Walk the field schedule with the team leads in the first week and read the 2025 lessons before touching the questionnaire.","at":"2026-10-08T07:24:59.809Z"},{"role":"ai","text":"Thank you, that covers the ground a successor would ask about. Press Complete to turn the answers into Expert Insights and item notes.","en":"Thank you, that covers the ground a successor would ask about. Press Complete to turn the answers into Expert Insights and item notes.","ar":"شكرًا لك، هذا يغطي ما سيسأل عنه الخلف. اضغط على إكمال لتحويل الإجابات إلى رؤى خبراء وملاحظات على العناصر.","at":"2026-10-08T07:24:59.809Z"}]', '{"titleEn":"Expert Insights: PRJ-15a Industrial Symbiosis Pilot","titleAr":"رؤى الخبراء: PRJ-15a Industrial Symbiosis Pilot","summaryEn":"Status: The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules. Watch out for: The 2024 round slipped because the station register arrived late. Where things live: The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account.","summaryAr":"الوضع: The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules. احذر من: The 2024 round slipped because the station register arrived late. مواقع الملفات: The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account.","statusEn":"The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules.","statusAr":"The environmental monitoring round for 2026 is 70 percent complete. The next milestone is the quality review on the 15th of next month, and the field teams already have their schedules.","decisions":[{"en":"We decided in March to move field data capture to tablets after the 2025 pilot cut the number of repeat site visits; the Programme Director approved it and the budget came from the data programme.","ar":"We decided in March to move field data capture to tablets after the 2025 pilot cut the number of repeat site visits; the Programme Director approved it and the budget came from the data programme."}],"contacts":[{"en":"Inside the Office, Saud Al-Shammari owns the operations calendar and Mohammed Al-Qarni runs the field teams.","ar":"Inside the Office, Saud Al-Shammari owns the operations calendar and Mohammed Al-Qarni runs the field teams."},{"en":"Outside, the contact at MEWA is the monitoring unit head, who cares about station location quality.","ar":"Outside, the contact at MEWA is the monitoring unit head, who cares about station location quality."}],"pitfalls":[{"en":"The 2024 round slipped because the station register arrived late.","ar":"The 2024 round slipped because the station register arrived late."},{"en":"Lock the register delivery date in writing and never start training before the data capture form is frozen.","ar":"Lock the register delivery date in writing and never start training before the data capture form is frozen."}],"locations":[{"en":"The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account.","ar":"The working files are in the DOP shared drive under /operations/2026, the final tables in the Vault, and the field logs in the tablet console; the data quality team holds the console admin account."}],"adviceEn":"Walk the field schedule with the team leads in the first week and read the 2025 lessons before touching the questionnaire.","adviceAr":"Walk the field schedule with the team leads in the first week and read the 2025 lessons before touching the questionnaire.","answers":6,"live":false}', 'complete', '01M4D6DC12577VFKBG6A0WFTZ8', '2026-10-08T07:24:59.805Z', '2026-10-08T07:24:59.815Z'),
('01M4D6DC1AZHWYJVECJHC7EAMV', '01M4D6DBY724ESZY5SW645WDA5', 'PRJ-19b Methane Leak Detection and Repair Programme', 'node', '01M4D6BHKAEWVDJKKTJCVV7TW5', '[{"role":"ai","text":"What is the current status of PRJ-19b Methane Leak Detection and Repair Programme, and what is the next milestone a successor must not miss?","en":"What is the current status of PRJ-19b Methane Leak Detection and Repair Programme, and what is the next milestone a successor must not miss?","ar":"ما الوضع الحالي لـ PRJ-19b Methane Leak Detection and Repair Programme، وما المحطة التالية التي لا ينبغي للخلف أن يفوّتها؟","at":"2026-10-08T07:24:59.818Z"},{"role":"person","text":"The review checklist is versioned in the Vault; the current one is v3 and the next revision waits for the monitoring team''s comments.","at":"2026-10-08T07:24:59.819Z"},{"role":"ai","text":"Which decisions shaped this work so far, and why were they taken?","en":"Which decisions shaped this work so far, and why were they taken?","ar":"ما القرارات التي شكّلت هذا العمل حتى الآن، ولماذا اتُّخذت؟","at":"2026-10-08T07:24:59.819Z"},{"role":"person","text":"We chose to keep the manual double-entry check for the first two months after the tablet rollout, because the automated rule caught only half of the coding errors in the pilot.","at":"2026-10-08T07:24:59.819Z"},{"role":"ai","text":"Who are the people a successor must know, inside Programme Office and outside it, and what does each one care about?","en":"Who are the people a successor must know, inside Programme Office and outside it, and what does each one care about?","ar":"من الأشخاص الذين ينبغي للخلف معرفتهم داخل المكتب وخارجه، وما الذي يهم كل واحد منهم؟","at":"2026-10-08T07:24:59.819Z"}]', NULL, 'in_progress', NULL, '2026-10-08T07:24:59.818Z', '2026-10-08T07:24:59.819Z');
