INSERT INTO "index_groups" ("id", "code", "name_en", "name_ar", "description_en", "description_ar", "colour_token", "sort", "is_active") VALUES
('01M4D6CBT17BP668W7AXE74782', 'sdg', 'SDGs', 'أهداف التنمية المستدامة', 'The seventeen Sustainable Development Goal scores from the Sustainable Development Report of the SDSN, with Saudi Arabia''s overall SDG Index score and rank.', 'درجات أهداف التنمية المستدامة السبعة عشر من تقرير التنمية المستدامة الصادر عن شبكة حلول التنمية المستدامة، مع درجة المملكة العربية السعودية وترتيبها في مؤشر أهداف التنمية المستدامة.', 'teal', 1, 1),
('01M4D6CBT24J4SZCFX6FFE8SNS', 'national', 'National Indicators', 'المؤشرات الوطنية', 'Headline indicators of Saudi Vision 2030 and the National Environment Strategy, read from the Statistics Hub with their targets.', 'المؤشرات الرئيسية لرؤية السعودية 2030 والاستراتيجية الوطنية للبيئة، مقروءة من مركز الإحصاءات مع مستهدفاتها.', 'navy', 2, 1),
('01M4D6CBT2MW46PV89EDWQWT7W', 'environment', 'Environment', 'البيئة', 'Environmental Performance Index, Climate Change Performance Index, protected areas, forest cover, air quality and the environmental SDGs.', 'مؤشر الأداء البيئي، ومؤشر أداء تغير المناخ، والمناطق المحمية، والغطاء الحرجي، وجودة الهواء، وأهداف التنمية المستدامة البيئية.', 'ok', 3, 1),
('01M4D6CBT2YW79Z7YE548CWXVM', 'climate', 'Climate', 'المناخ', 'ND-GAIN climate adaptation, Climate Change Performance, greenhouse gas emissions per capita and the renewable share of energy.', 'التكيف المناخي وفق مؤشر ND-GAIN، وأداء تغير المناخ، وانبعاثات غازات الدفيئة للفرد، وحصة الطاقة المتجددة.', 'aqua', 4, 1),
('01M4D6CBT28F6ZEQ78GXHHRSWD', 'water', 'Water Security', 'الأمن المائي', 'Aqueduct baseline water stress, freshwater withdrawals, renewable water per capita and access to basic drinking water.', 'الإجهاد المائي الأساسي وفق Aqueduct، والسحب السنوي للمياه العذبة، ونصيب الفرد من المياه المتجددة، والوصول إلى مياه الشرب الأساسية.', 'info', 5, 1),
('01M4D6CBT2S7658ANBY0SZX50W', 'agriculture', 'Agriculture and Food Security', 'الأمن الغذائي والزراعة', 'Food production, cereal yield, forest and vegetation cover and the zero hunger and life on land goals.', 'إنتاج الأغذية، وإنتاجية الحبوب، والغطاء الحرجي والنباتي، وهدفا القضاء على الجوع والحياة في البر.', 'ink', 6, 1),
('01M4D6CBT393PRVET39N8JSSTS', 'governance', 'Governance and Institutions', 'الحوكمة والمؤسسات', 'Corruption Perceptions and the Worldwide Governance Indicators, the institutional context of environmental regulation.', 'مدركات الفساد ومؤشرات الحوكمة العالمية، وهي السياق المؤسسي للتنظيم البيئي.', 'navy', 7, 1),
('01M4D6CBT3ENKR5NM0JTNZY0SM', 'human', 'Human Development and Society', 'التنمية البشرية والمجتمع', 'Human Development and Social Progress.', 'التنمية البشرية والتقدم الاجتماعي.', 'teal', 8, 1);
